/**
 * Regenerates packages/agent/src/config/builtin-assets.generated.ts.
 *
 * Adapted from BreachWeave's scripts/generate-builtin-assets.ts after trimming the
 * vendored tree (unused skills removed). Run with:
 *
 *   bun run tools/vendor/generate-agent-assets.ts
 */

import { readdirSync, statSync } from "node:fs";
import { basename, extname, relative, resolve } from "node:path";

const projectRoot = resolve(import.meta.dir, "..", "..");
const configDir = resolve(projectRoot, "packages/agent/src/config");
const promptsBuiltinDir = resolve(configDir, "prompts/builtin");
const skillsBuiltinDir = resolve(configDir, "skills/builtin");
const runtimeAssetsDir = resolve(projectRoot, "packages/agent/src/runtime/assets");
const outputPath = resolve(configDir, "builtin-assets.generated.ts");

function collectFiles(dir: string): string[] {
  const files: string[] = [];

  function walk(currentDir: string) {
    for (const entry of readdirSync(currentDir)) {
      if (entry.startsWith(".")) continue;
      const fullPath = resolve(currentDir, entry);
      if (statSync(fullPath).isDirectory()) {
        walk(fullPath);
      } else {
        files.push(relative(configDir, fullPath).replaceAll("\\", "/"));
      }
    }
  }

  walk(dir);
  return files.sort();
}

function escapeIdentifier(value: string): string {
  return value.replace(/[^a-zA-Z0-9_]/g, "_");
}

function shouldIncludeBuiltinSkillFile(file: string): boolean {
  const ext = extname(file).toLowerCase();
  if ([".md", ".txt", ".json", ".sh", ".yaml", ".yml"].includes(ext)) return true;
  if (!ext && file.includes("/scripts/")) return true;
  return basename(file) === "SKILL";
}

const promptFiles = collectFiles(promptsBuiltinDir).filter((file) => file.endsWith(".md"));
const skillFiles = collectFiles(skillsBuiltinDir).filter(shouldIncludeBuiltinSkillFile);
const runtimeFiles = collectFiles(runtimeAssetsDir);

const lines: string[] = [
  "// generated by tools/vendor/generate-agent-assets.ts",
  "// Vendored from BreachWeave; regenerate after changing prompts, skills or runtime assets.",
];

promptFiles.forEach((file, index) => {
  lines.push(`import prompt_${index} from "./${file}" with { type: "file" }`);
});
skillFiles.forEach((file, index) => {
  lines.push(`import skill_${index} from "./${file}" with { type: "file" }`);
});
runtimeFiles.forEach((file, index) => {
  lines.push(`import runtime_${index} from "${file}" with { type: "file" }`);
});

lines.push("", "export const BUILTIN_PROMPTS = {");
promptFiles.forEach((file, index) => {
  lines.push(
    `  ${JSON.stringify(file.slice("prompts/builtin/".length))}: prompt_${index},`,
  );
});
lines.push("} as const", "", "export const BUILTIN_SKILL_FILES = {");
skillFiles.forEach((file, index) => {
  lines.push(
    `  ${JSON.stringify(file.slice("skills/builtin/".length))}: skill_${index},`,
  );
});
lines.push("} as const", "", "export const RUNTIME_ASSET_FILES = {");
runtimeFiles.forEach((file, index) => {
  lines.push(
    `  ${JSON.stringify(file.slice("../runtime/assets/".length))}: runtime_${index},`,
  );
});
lines.push("} as const", "");

await Bun.write(outputPath, lines.join("\n"));
console.log(
  `wrote ${outputPath} (${promptFiles.length} prompts, ${skillFiles.length} skill files, ${runtimeFiles.length} runtime assets)`,
);
